SourceCode.Declaration:
/// <summary>
/// A store's virtual bins: where in a location stock sits. Used by counting only, to record where
/// a count was made. D365FO's on-hand stays at location level and knows nothing of bins. A store
/// with no bins here counts by location alone, as before.
/// </summary>
public class HSMobileOpsCountBin extends common
{
}

Method.Source:
public void initValue()
{
    super();
    this.Active = NoYes::Yes;
}

public static HSMobileOpsCountBin find(InventLocationId _warehouse, str _binId, boolean _forUpdate = false)
{
    HSMobileOpsCountBin bin;

    bin.selectForUpdate(_forUpdate);
    select firstOnly bin
        where bin.InventLocationId == _warehouse
           && bin.BinId            == _binId;
    return bin;
}
